class FastPrinter:
    def print_doc(self, text): print("Fast:", text)

class SlowPrinter:
    def print_doc(self, text, ink_level): print("Slow:", text)

def print_report(provider):
    provider.print_doc("Annual Report")

print_report(FastPrinter())
